    sum += sampleBlitzShadowTap(shadowCoord.xy + vec2(0.4910, 0.6258) * radius, zRef);
    sum += sampleBlitzShadowTap(shadowCoord.xy + vec2(-0.8856, -0.2512) * radius, zRef);
